import{_ as p,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"3、【屯】 震下坎上","description":"周易闡真 - 3、【屯】 震下坎上","frontmatter":{"title":"3、【屯】 震下坎上","description":"周易闡真 - 3、【屯】 震下坎上"},"headers":[],"relativePath":"classics/chanzhen/004.md","filePath":"classics/chanzhen/004.md"}'),s={name:"classics/chanzhen/004.md"};function n(c,a,i,o,l,h){return t(),e("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：屯，剛柔始交而難生，動乎險中，大亨貞。雷雨之動滿盈，天造草昧，宜建侯而不寧。</p></blockquote><h1 id="_3、【屯】-震下坎上" tabindex="-1">3、【屯】 震下坎上 <a class="header-anchor" href="#_3、【屯】-震下坎上" aria-label="Permalink to “3、【屯】 震下坎上”">​</a></h1><p>初九：磐桓，利居貞，利建侯。</p><p>六二：屯如邅如，乘馬班如，匪寇婚媾。女子貞，不字，十年乃字。</p><p>六三：即鹿無虞，惟入於林中，君子幾不如舍，往吝。</p><p>六四：乘馬班如，求婚媾，往吉，無不利。</p><p>九五：屯其膏，小貞吉，大貞兇。</p><p>上六：乘馬班如，泣血漣如。</p><h2 id="孔易闡真-​" tabindex="-1">孔易闡真 ​ <a class="header-anchor" href="#孔易闡真-​" aria-label="Permalink to “孔易闡真 ​”">​</a></h2><p>大象：雲雷屯，君子以經綸。</p><p>屯者，屈而未伸之義。上坎水，下震雷，坎言云而不言水者，雨自雲而降，雷在雲中震動，已有雨意，未至雨時，正陰陽搏結，將通未通之候，屯之象也。</p><p>君子有見於此，知先天一點陽氣，為後天陰氣所陷，雖有發現之時，屯難不通，若無扶陽抑陰之功，難得易失，當面錯過。以是因其所發，而經綸修持焉。經者，整其緒，調合陰陽是也；綸者，理其條，加減進退是也。經而不綸，不能成物；知藥物而不知火候，不能成道。當一陽生於坎地，正陰陽交接之關口，生殺相分之要津，可兇可吉之時。修道者急須下手，扭轉旋璣，謹守靈苗，不使陰氣稍有侵傷，漸生漸採，十二時中無有間斷，經之綸之，進退止足，毫髮不差，雖始而陽氣不通，終而陽氣舒暢，亦如雷震於雲中，甘露自降，所謂昏久則昭明者是也。</p><h2 id="悟元子註解-​" tabindex="-1">悟元子註解 ​ <a class="header-anchor" href="#悟元子註解-​" aria-label="Permalink to “悟元子註解 ​”">​</a></h2><p>幾，音機。舍，音捨。</p><p>屯者，前進有難之義，卦德上坎陷，下震動，動於險中，險中之動，不易出險，故謂屯。</p><p>此進陽下手之卦，承上乾卦而來。乾為健德，進陽者即進其健，因其不健而進於健耳。健德為先天真陽，本來正氣。這個氣交於後天，隱而不現，然雖不現，未嘗全泯，間有發現之時，特人為世事所迷，妄念所蔽，當面錯過，不肯認真耳。當其發現之時，即吾身中活子時也。這個時，與天地合其德，與日月合其明，與四時合其序，與鬼神合其吉凶，乃陰陽之門，生死之戶，性命之源，健順之根，造命之鼎，偃月之爐。先天真陽元氣在此，知之者，勤而修之，於後天中返先天，自微而著，由一陽而漸生漸長，必至六陽純全，是屯中又有元亨之道也。</p><p>但人為氣質所拘、積習所染，先天真陽，埋沒已深，雖有回覆之時，然正氣弱而邪氣盛，正不勝邪，未能遽然增升，是在乎謹封牢藏，守此一點生機，不為客氣所傷，以為返還之本，故曰“利貞”，又曰“勿用，有攸往。”貞非空空無為，勿往非絕無一事，特以人心用事已久，道心不彰，陰中返陽，乃險中之動，若冒然下手，速欲成功，愈滋其險，欲返其陽，莫若先正其心。</p><p>曰“利建侯”者，即是正心之象。侯為一國之主，心為一身之主。建侯則一國之難漸可治，正心則一身之險漸可消。心若一正，根本堅固，元氣不散，於是隨時進火，漸採漸煉，則已失者可以得，已去者可以還。利於貞而動，動不妄動，動必以時，元而未有不亨，亨而未有不利者也。</p><p>初九，剛居屯初，陽氣下伏，如大廈之盤桓，利於居貞，而堅固根本，如一國之君侯，利於建侯，而培植元氣。此遇屯而須當守正於始也。</p><p>六二，正在屯中，故屯如邅如，柔順中正，煉己待時，故乘馬班如。其乘馬班如，欲動而不動者，非以其初生之陽，有所寇傷於人，特欲待其陰陽相當，方求婚媾配合耳。其待時婚媾之象，如女子貞不字，十年乃字矣。此在屯而不遽求其濟也。</p><p>六三，無知小人，愚而自用，妄貪天寶，本險而又行險，如即鹿無虞，惟入於林中，亦無足怪。至於明道君子，須當知幾，不如舍之以待時。若不待時，急欲成功，往而前進，必有招險之吝。此在屯而急欲求其濟也。</p><p>六四，柔而得正，煉己待時，真陽在望，正當調和丹頭之時，不可當面錯過者，是以求婚媾往吉，無不利。此在屯而隨時求其濟也。</p><p>九五，陽剛中正，聖胎有象，已實其腹，如有膏矣。然聖胎雖結，陰氣未退，尚在險中，如屯其膏矣。當此之時，有為事畢，無為事彰，是以“小貞吉，大貞兇”。此大而知小，待時而能出屯也。</p><p>上六，在屯之終，正是出屯之時，柔而無能，乘馬班如，措手無策，雖真陽在望，未許我得，泣血漣如，何益於事?此小而不能大，無屯而亦有屯也。</p><p>大抵進陽運火之道，須要知時，知時採藥，借後天返先天，可以出屯，可以濟屯。若不知時，過與不及，真陽終為陰氣所陷，而不得出，故卦辭曰：“元亨，利貞。”貞而方能利，利則元而未有不亨，利貞之元亨，其即待時出屯之義歟?</p>',25)])])}const m=p(s,[["render",n]]);export{d as __pageData,m as default};
